    fputs("                                build/<name>/ with lib<name>.a, <name>.h, <name>.lar, <name>.interface\n", stdout);
    fputs("  larimar build --static | --dynamic  a library of that kind, instead of [library] type\n", stdout);
    fputs("  larimar run [folder] [-- args] build, then run it with the arguments\n", stdout);
